document.addEventListener("DOMContentLoaded", () => {
  if (!localStorage.getItem("currentUser"))
    return void (window.location.href = "auth.html");
  const e = document.querySelector(".hamburger-menu"),
    t = document.querySelector(".main-nav");
  e &&
    t &&
    e.addEventListener("click", () => {
      (t.classList.toggle("open"),
        e.setAttribute("aria-expanded", String(t.classList.contains("open"))));
    });
  const n = document.querySelector(".cart-badge"),
    o = (JSON.parse(localStorage.getItem("cart")) || []).reduce(
      (e, t) => e + t.quantity,
      0,
    );
  n && ((n.textContent = o), (n.style.display = o > 0 ? "flex" : "none"));
});
